#include "rigid.hpp"
#include <iostream>
#include <fstream>
#include <iomanip>
#include <filesystem>
using namespace rigid;
std::ofstream attempts;
int macro;
std::string variant;
Result audit(const Model&m,const State&s,double h,const Scale&q,const std::string&base,int depth=0){Result a=raw(m,s,h,q,base),b=raw(m,s,h/2,q,base),c=b.ok?raw(m,b.s,h/2,q,base):b;double diff=a.ok&&b.ok&&c.ok?(encode(a.s,q)-encode(c.s,q)).norm():1e9;if(variant=="mass_weighted"&&a.ok&&b.ok&&c.ok){V delta=encode(a.s,q)-encode(c.s,q),weights=V::Zero(delta.size());weights.head(s.x.size())=masses(m)/m.mass.mean();weights.tail(s.v.size())=masses(m)/m.mass.mean();diff=std::sqrt((delta.array().square()*weights.array()).sum());}double tolerance=(variant=="loose"?1e-3:1e-4)*std::abs(h);bool pass=a.ok&&b.ok&&c.ok&&diff<tolerance;attempts<<variant<<","<<base<<","<<macro<<","<<depth<<","<<h<<","<<pass<<","<<a.ok<<","<<b.ok<<","<<c.ok<<","<<a.reason<<","<<b.reason<<","<<c.reason<<","<<diff<<","<<tolerance<<","<<a.residual<<","<<b.residual<<","<<c.residual<<"\n";int it=a.iterations+b.iterations+c.iterations,ev=a.evaluations+b.evaluations+c.evaluations;if(pass){c.iterations=it;c.evaluations=ev;c.leaves=2;return c;}if(depth==(variant.find("deep")!=std::string::npos?16:12)){c.ok=false;c.reason="depth_limit";return c;}Result l=audit(m,s,h/2,q,base,depth+1);if(!l.ok)return l;Result r=audit(m,l.s,h/2,q,base,depth+1);r.iterations+=it+l.iterations;r.evaluations+=ev+l.evaluations;r.leaves+=l.leaves;r.rejections+=l.rejections+1;return r;}
int main(){std::filesystem::create_directories("controller_probe");attempts.open("controller_probe/attempts.csv");attempts<<std::setprecision(16)<<"variant,method,macro,depth,h,accepted,full_ok,half1_ok,half2_ok,full_reason,half1_reason,half2_reason,doubling_gap,tolerance,full_residual,half1_residual,half2_residual\n";std::ofstream result("controller_probe/summary.csv");result<<std::setprecision(16)<<"variant,method,status,steps_done,steps_requested,position_rms,max_energy_relative,max_tangency,residual_evaluations,accepted_substeps,reference_gap\n";Case c;for(auto cc:cases())if(cc.name=="double_heavy_tip")c=cc;Scale q=scales(c.model,c.initial);double h=1./30;std::vector<State>ref{c.initial};V zz=angles(c.model,c.initial),zz2=zz;double reference_gap=0;for(int i=0;i<30;++i){zz=rk4(c.model,zz,h,512);zz2=rk4(c.model,zz2,h,1024);ref.push_back(cartesian(c.model,zz2));reference_gap=std::max(reference_gap,(encode(cartesian(c.model,zz),q)-encode(ref.back(),q)).norm());}for(std::string v:{"default","tight","deep","deep_tight","mass_weighted","loose"})for(std::string base:{"rattle","sym_energy","canonical_dg"}){variant=v;solver_tolerance=v.find("tight")!=std::string::npos?3e-14:3e-11;solver_fallback=v.find("tight")!=std::string::npos?2e-12:2e-9;State s=c.initial;int done=0,ev=0,leaves=0;double sum=0,maxE=0,maxT=0;std::string status="complete";for(macro=0;macro<30;++macro){Result a=audit(c.model,s,h,q,base);ev+=a.evaluations;leaves+=a.leaves;if(!a.ok){status=a.reason;break;}s=a.s;++done;sum+=(s.x-ref[macro+1].x).squaredNorm()/c.model.count;maxE=std::max(maxE,std::abs(energy(c.model,s)-energy(c.model,c.initial))/q.e);maxT=std::max(maxT,(gradient(c.model,s.x)*s.v).norm()/(q.l*q.v));}result<<v<<","<<base<<","<<status<<","<<done<<",30,"<<std::sqrt(sum/std::max(done,1))<<","<<maxE<<","<<maxT<<","<<ev<<","<<leaves<<","<<reference_gap<<"\n";} }
